 trview(d){const t=(PAGE.trials&&PAGE.trials.trials||[]).find(x=>x.id===d.id);if(!t)return;modal('<h2>Trial '+esc(t.id)+'</h2><p class="sm mt">Result: <b>'+t.result+'</b>'+(t.finalScore!=null?' — '+t.finalScore+'/5':'')+'</p><p class="sm mut mt">Scores: '+Object.entries(t.scores||{}).map(([k,v])=>k+': '+(v==null?'–':v)).join(' · ')+'</p>'+(t.adminNotes?'<p class="sm mut mt">Feedback: '+esc(t.adminNotes)+'</p>':''))},
 kycdec(d){const v=d.v,docs=(PAGE.kycSum&&PAGE.kycSum.documents||PAGE.kycDocs||[]),t=docs.find(x=>x.id===d.id)||{};
  const ref='<p class="sm mut">'+esc(d.id)+((t.panditName||t.name)?' · '+esc(t.panditName||t.name):'')+'</p>';
  if(v==='REJECTED')modal('<h2>Reject document</h2>'+ref+'<div class="frm mt"><label class="f">Rejection reason (the pandit will see exactly this)<textarea id="kycwhy" style="min-height:80px"></textarea></label></div><button class="btn bad mt" data-act="kycdecok" data-id="'+esc(d.id)+'" data-v="REJECTED">Reject document</button>');
  else if(v==='REVERIFICATION_REQUIRED')modal('<h2>Request re-upload</h2>'+ref+'<div class="frm mt"><label class="f">What must be re-uploaded and why<textarea id="kycwhy" style="min-height:80px"></textarea></label></div><button class="btn mt" data-act="kycdecok" data-id="'+esc(d.id)+'" data-v="REVERIFICATION_REQUIRED">Request re-upload</button>');
  else if(v==='VERIFIED')modal('<h2>Verify document</h2>'+ref+'<div class="frm mt"><label class="f">Valid for how many days<input id="kycdays" type="number" min="1" value="730"></label><p class="sm mut mt">Leave empty for no expiry. The pandit is notified with the decision.</p></div><button class="btn mt" data-act="kycdecok" data-id="'+esc(d.id)+'" data-v="VERIFIED">Verify document</button>');
  else run(()=>api('/admin/kyc/'+d.id+'/decide',{body:{status:v}}),'KYC decision recorded').then(()=>{PAGE.kycSum=null;sync().then(()=>render(true))})},
 async kycdecok(d){const v=d.v,body={status:v};
  if(v==='REJECTED'||v==='REVERIFICATION_REQUIRED'){const why=(val('kycwhy')||'').trim();if(!why)return toast('This reason is required — the pandit sees it exactly');body.reason=why}
  else if(v==='VERIFIED'){const days=val('kycdays');if(days&&Number(days)>0)body.expiresAt=Date.now()+Number(days)*86400000}
  await closeAnd(run(()=>api('/admin/kyc/'+d.id+'/decide',{body}),'KYC decision recorded'));
  PAGE.kycSum=null;sync().then(()=>render(true))},
 plc(d){const v=d.v;
  if(v==='SUSPENDED'||v==='TERMINATED'){const susp=v==='SUSPENDED';
   modal('<h2>'+(susp?'Suspend':'Terminate')+' pandit '+esc(d.id)+'</h2><p class="sm mut mt">This blocks login immediately (existing sessions revoked) and places open payouts ON HOLD'+(susp?'':' — termination is final, there is no reinstatement')+'.</p><div class="frm mt"><label class="f">Reason (documented, required)<textarea id="plcr" style="min-height:70px"></textarea></label>'+(susp?'<div class="row"><label class="f" style="flex:1">Suspension end date (optional)<input type="date" id="plct"></label><label class="f" style="flex:1">Review date (optional)<input type="date" id="plcrd"></label></div>':'')+'</div><button class="btn bad mt" data-act="plcok" data-id="'+esc(d.id)+'" data-v="'+v+'">Confirm '+(susp?'suspension':'termination')+'</button>')}
  else if(v==='UNDER_REVIEW')modal('<h2>Mark for review</h2><p class="sm mut mt">What needs review? The note is kept with the lifecycle record.</p><div class="frm mt"><label class="f">Review note<textarea id="plcr" style="min-height:70px"></textarea></label></div><button class="btn mt" data-act="plcok" data-id="'+esc(d.id)+'" data-v="UNDER_REVIEW">Continue</button>');
  else run(()=>api('/admin/pandits/'+d.id+'/lifecycle',{body:{lifecycle:v}}),'Account lifecycle updated').then(()=>{PAGE.lc=null;PAGE.accts=null;sync().then(()=>render(true))})},
 async plcok(d){const v=d.v,body={lifecycle:v},why=(val('plcr')||'').trim();if(!why)return toast('A reason is required and is kept on record');
  if(v==='SUSPENDED'||v==='TERMINATED'){body.reason=why;const to=val('plct'),rd=val('plcrd');if(to)body.to=to;if(rd)body.reviewDate=rd}
  else body.note=why;
  await closeAnd(run(()=>api('/admin/pandits/'+d.id+'/lifecycle',{body}),'Account lifecycle updated'));
  PAGE.lc=null;PAGE.accts=null;sync().then(()=>render(true))},
