 async acholds(d){try{const r=await api('/admin/customer-holds/'+d.id),bs=r.bookings||[],cn=(r.customer&&r.customer.n)||d.id;
  const rows=bs.map(b=>[b.id,esc((PU(b.pujaId)||{n:b.pujaId}).n),fmtD(b.date)+'<br><span class="sm mut">'+b.slot+'</span>',badge(b.status),'<button class="btn s" data-act="achold1" data-id="'+b.id+'">Release</button>']);
  modal('<h2>Held bookings — '+esc(cn)+'</h2><p class="sm mut mt">'+(bs.length?bs.length+' booking'+(bs.length>1?'s are':' is')+' held under the customer review flag. Releasing clears the flag per booking; fulfilment itself was never blocked.':'No bookings are currently held for this customer.')+'</p>'+(bs.length?'<div class="tw mt"><table><thead><tr><th>Booking</th><th>Puja</th><th>When</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((c,i)=>'<td'+(i===4?' style="white-space:nowrap"':'')+'>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="row mt"><button class="btn" data-act="acholdsok" data-id="'+esc(d.id)+'">Release all '+bs.length+'</button><button class="btn ghost" data-act="close">Close</button></div>':'<div class="row mt"><button class="btn ghost" data-act="close">Close</button></div>'),1)}catch(e){toast(e.message)}},
