 anridel(d){modal('<h2>Delete this NRI package?</h2><p class="sm mut mt">Packages with past orders cannot be deleted — take them off sale instead.</p><div class="frm mt"><label class="f">Reason (required, audited)<textarea id="anridelr" style="min-height:70px"></textarea></label></div><div class="row mt"><button class="btn bad" data-act="anridelok" data-id="'+esc(d.id)+'">Delete package</button><button class="btn ghost" data-act="close">Keep package</button></div>')},
