 async anriadd(){const includes=$('#nrx2').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!val('nrn2'))return toast('Name required');const r=await run(()=>api('/admin/nri-packages',{body:{name:val('nrn2'),descr:val('nrd2'),price:+val('nrp2'),currency:val('nrc2'),inrEquiv:+val('nri2'),includes,active:true}}),'Package added');if(r){PAGE.nriAdmin=null;sync().then(()=>render(true))}},
 apuedit(d){const p=PU(d.id);if(!p)return;
  const MODEPRICE=[['priceHome','Home'],['priceOnline','Online'],['priceTemple','Temple'],['priceCustom','Customized']];
  modal('<h2>Edit puja</h2><div class="frm mt"><label class="f">Name<input id="pen" value="'+esc(p.n)+'"></label><label class="f">Hindi name<input id="peh" value="'+esc(p.h||'')+'"></label><label class="f">Category<input id="pec" value="'+esc(p.cat||'')+'"></label><label class="f">Deity<input id="ped" value="'+esc(p.deity||'')+'"></label><label class="f">Benefits (English)<textarea id="peb">'+esc(p.ben||'')+'</textarea></label><label class="f">लाभ (Hindi)<textarea id="pebh">'+esc(p.benHi||'')+'</textarea></label><div class="row mt"><label class="f" style="flex:1">Duration (min)<input id="pedu" type="number" value="'+p.dur+'"></label><label class="f" style="flex:1">Base price<input id="pep" type="number" value="'+p.price+'"></label></div><p class="sm mut mt">Per-mode prices (₹, optional — empty uses the base price and puja type)</p><div class="row mt">'+MODEPRICE.map(([k,l])=>'<label class="f" style="flex:1">'+l+'<input id="pe_'+k+'" type="number" placeholder="auto" value="'+(p[k]!=null?p[k]:'')+'"></label>').join('')+'</div><p class="sm mut mt">Bookable puja types</p><div class="row mt" style="flex-wrap:wrap">'+Object.entries(MODES).map(([mk,md])=>'<label class="chip"><input type="checkbox" class="pem" value="'+mk+'" '+(p.modes.includes(mk)?'checked':'')+'> '+md.i+' '+md.n+'</label>').join('')+'</div><label class="f mt">Samagri kit<select id="pek">'+KITS.map(k=>'<option value="'+k.id+'"'+(p.kit===k.id?' selected':'')+'>'+k.n+'</option>').join('')+'</select></label><label class="row mt"><input type="checkbox" id="pev" '+(p.hidden?'':'checked')+'> Visible in catalogue</label><button class="btn mt" data-act="apueditok" data-id="'+esc(p.id)+'">Save puja</button></div>')},
