 adel(d){modal('<h2>Delete this temple?</h2><p class="sm mut mt">Temples with past bookings cannot be deleted — delist them instead.</p><div class="frm mt"><label class="f">Reason (required, audited)<textarea id="adelr" style="min-height:70px"></textarea></label></div><div class="row mt"><button class="btn bad" data-act="adelok" data-id="'+esc(d.id)+'">Delete temple</button><button class="btn ghost" data-act="close">Keep temple</button></div>')},
