 /* Additional-requirements Phase B: Our People admin CMS. */
 pgal(d){const p=PAGE.person;if(!p||!(p.photos||[]).length)return;PAGE.gal={pujaId:'person-'+(p.id||''),cat:'',offset:p.photos.length,items:p.photos.map(x=>Object.assign({altText:x.caption||p.n},x)),total:p.photos.length};openLightbox(+d.i||0)},
 pnew(){modal('<h2>Add a person</h2><p class="sm mut mt">They appear on the public Our People page as soon as the profile is visible.</p><div class="mt">'+pFormHtml(null)+'</div><div class="row mt"><button class="btn" data-act="pnewok">Add person</button><button class="btn ghost" data-act="close">Cancel</button></div>',1)},
