 pedit(d){const p=(db.peopleAdmin||[]).find(x=>x.id===d.id);if(!p)return;modal('<h2>Edit person</h2><div class="mt">'+pFormHtml(p)+'</div><div class="mt"><h3>Photos</h3><p class="sm mut mt">Profile photo and gallery for this person.</p><div class="row mt"><button class="btn s" data-act="pphoto" data-id="'+esc(p.id)+'">Manage photos</button></div></div><div class="row mt"><button class="btn" data-act="peditok" data-id="'+esc(p.id)+'">Save profile</button><button class="btn ghost" data-act="close">Cancel</button></div>',1)},
