 pphoto(d){const p=(db.peopleAdmin||[]).find(x=>x.id===d.id);if(!p)return;
  const gal=(p.photos||[]).length?(p.photos||[]).map(x=>'<div class="card flat" style="width:150px;padding:8px"><img src="'+esc(mediaUrl(x.thumb||x.url))+'" alt="'+esc(x.caption||p.n)+'" style="width:100%;height:90px;object-fit:cover;border-radius:8px"><div class="sm mt">'+esc(x.caption||'')+'</div><button class="btn s bad mt" data-act="pgaldel" data-id="'+esc(x.id)+'" data-name="'+esc(p.n)+'">Delete</button></div>').join(''):'<p class="sm mut mt">No gallery photos yet.</p>';
  modal('<h2>Photos — '+esc(p.n)+'</h2><div class="grid g2 mt2"><div class="card"><h3>Profile photo</h3>'+(p.photo?'<img src="'+esc(mediaUrl(p.photoThumb||p.photo))+'" alt="'+esc(p.n)+'" style="width:120px;height:120px;object-fit:cover;border-radius:10px">':'<p class="sm mut mt">No profile photo yet — the initials avatar is shown.</p>')+'<label class="f mt">Upload or replace<input type="file" id="ppf" accept="image/*"></label><div class="row mt"><button class="btn s" data-act="pphotoup" data-id="'+esc(p.id)+'">Upload photo</button>'+(p.photo?'<button class="btn s bad" data-act="pphotoclear" data-id="'+esc(p.id)+'">Remove</button>':'')+'</div></div><div class="card"><h3>Gallery</h3><div class="row" style="flex-wrap:wrap;gap:10px">'+gal+'</div><label class="f mt">Add a photo<input type="file" id="pgf" accept="image/*"></label><label class="f">Caption<input id="pgc"></label><button class="btn s mt" data-act="pgalup" data-id="'+esc(p.id)+'">Add to gallery</button></div></div><p class="sm mut mt">Images are stored as the original plus a 320px thumbnail and WebP variants. Content is verified before anything is written.</p><div class="row mt"><button class="btn ghost" data-act="close">Close</button></div>',1)},
 async pphotoup(d){const f=$('#ppf')&&$('#ppf').files&&$('#ppf').files[0];if(!f)return toast('Choose a photo first');const fd=new FormData();fd.append('photo',f);try{await api('/admin/people/'+d.id+'/photo',{form:fd});toast('Profile photo updated');closeModal();await sync();render(true)}catch(e){toast(e.message)}},
