 pcnew(){modal('<h2>Add a category</h2><p class="sm mut mt">Categories group the public Our People page in order. The nine defaults can be renamed or reordered but keep their ids.</p><div class="frm mt"><label class="f">Name<input id="pcn"></label><label class="f">Display order<input id="pco" type="number" min="0" placeholder="after the last"></label></div><button class="btn mt" data-act="pcnewok">Add category</button>')},
