 /* Additional-requirements Phase D: Photo + Video Gallery. Public views read
    the paged cache in PAGE.gv (seeded from /state, extended by gmore); the
    lightbox is the shared one, videos play in a modal embed. Admin handlers
    mirror the people CMS: every destructive action asks for an audited reason. */
 gopen(d){const gv=PAGE.gv;if(!gv||!gv.items.length)return;const a=gv.album?galAlbum(gv.album):null;PAGE.gal={cat:a?a.n:'',offset:gv.items.length,items:gv.items,total:gv.total};openLightbox(+d.i||0)},
 async gmore(){const gv=PAGE.gv;if(!gv||gv.nextOffset==null)return;try{const x=await api('/gallery?kind='+gv.kind+'&limit=12&offset='+gv.nextOffset+(gv.album?'&album='+encodeURIComponent(gv.album):''));const add=gv.kind==='videos'?x.videos:x.photos;gv.items=gv.items.concat(add||[]);gv.nextOffset=x.nextOffset;render(true)}catch(e){toast(e.message)}},
 vplay(d){const gv=PAGE.gv;const vids=((db.gallery||{}).videos||[]).concat(gv&&gv.kind==='videos'?gv.items:[]);const v=vids.find(x=>x.id===d.id);if(!v)return;if(!v.yt)return window.open(v.url,'_blank','noopener');
  modal('<h2>'+esc(v.n)+'</h2><div class="tw mt"><iframe style="width:100%;aspect-ratio:16/9;border:0;border-radius:10px" src="https://www.youtube.com/embed/'+v.yt+'" title="'+esc(v.n)+'" allowfullscreen allow="accelerometer; autoplay; encrypted-media; picture-in-picture"></iframe></div>'+(v.d?'<p class="sm mut mt">'+esc(v.d)+'</p>':'')+'<p class="sm mt"><a href="'+esc(v.url)+'" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a></p><div class="row mt"><button class="btn ghost" data-act="close">Close</button></div>',1)},
 /* albums */
 galbnew(){modal('<h2>Add an album</h2><p class="sm mut mt">Albums group the public gallery. Deleting an album later keeps its photos and videos — they simply become un-albumed.</p><div class="frm mt"><label class="f">Name<input id="galbn"></label><label class="f">Description<textarea id="galbd" style="min-height:60px"></textarea></label><label class="f">Display order<input id="galbo" type="number" min="0" placeholder="after the last"></label></div><button class="btn mt" data-act="galbnewok">Add album</button>')},
