 galbdel(d){modal('<h2>Delete this album?</h2><p class="sm mut mt">The album is removed, but its photos and videos are KEPT — they become un-albumed and stay in the public gallery. Delete the photos themselves if you want them gone. The deletion is audited with your reason.</p><div class="frm mt"><label class="f">Reason (required, audited)<textarea id="gabdr" style="min-height:70px"></textarea></label></div><div class="row mt"><button class="btn bad" data-act="galbdelok" data-id="'+esc(d.id)+'">Delete album</button><button class="btn ghost" data-act="close">Keep album</button></div>')},
