 galvdel(d){modal('<h2>Delete this video?</h2><p class="sm mut mt">The link is removed from the gallery (nothing is downloaded or stored). The deletion is audited with your reason.</p><div class="frm mt"><label class="f">Reason (required, audited)<textarea id="galvdr" style="min-height:70px"></textarea></label></div><div class="row mt"><button class="btn bad" data-act="galvdelok" data-id="'+esc(d.id)+'">Delete video</button><button class="btn ghost" data-act="close">Keep video</button></div>')},
