 ptrans(d){const id=d.id,act=d.v;const ok=()=>{PAGE.accts=null;sync().then(()=>render(true))};
  if(act==='process')run(()=>api('/admin/payouts/'+id+'/process',{body:{}}),'Payout moved to PROCESSING').then(ok);
  else if(act==='hold')modal('<h2>Place payout '+esc(id)+' ON HOLD</h2><div class="frm mt"><label class="f">Hold reason (the pandit will see exactly this)<input id="pthr" value="Customer Dispute"></label><label class="f">Internal note (optional)<textarea id="pthn" style="min-height:60px"></textarea></label></div><button class="btn bad mt" data-act="ptholdok" data-id="'+esc(id)+'">Place ON HOLD</button>');
  else if(act==='disburse')modal('<h2>Disburse payout '+esc(id)+'</h2><div class="frm mt"><label class="f">Payment reference (bank ref / UPI txn, required)<input id="ptpr"></label><label class="f">UTR (optional)<input id="ptutr"></label></div><button class="btn mt" data-act="ptdisbok" data-id="'+esc(id)+'">Confirm disbursement</button>');
  else if(act==='fail')modal('<h2>Mark payout '+esc(id)+' FAILED</h2><div class="frm mt"><label class="f">Reason (required)<textarea id="ptwhy" style="min-height:70px"></textarea></label></div><button class="btn bad mt" data-act="ptfailok" data-id="'+esc(id)+'">Mark FAILED</button>');
  else if(act==='reverse')modal('<h2>Reverse payout '+esc(id)+'</h2><p class="sm mut mt">This payout was already disbursed. Reversal requires a documented reason.</p><div class="frm mt"><label class="f">Reason for reversing (required)<textarea id="ptwhy" style="min-height:70px"></textarea></label></div><button class="btn bad mt" data-act="ptrevok" data-id="'+esc(id)+'">Reverse payout</button>');
  else if(act==='adjust')modal('<h2>Adjust payout '+esc(id)+'</h2><p class="sm mut mt">Positive adds to the payout, negative deducts. The reason is kept on record.</p><div class="frm mt"><label class="f">Amount (negative to deduct)<input id="ptamt" type="number" step="1"></label><label class="f">Reason<textarea id="ptwhy" style="min-height:60px"></textarea></label></div><button class="btn mt" data-act="ptadjok" data-id="'+esc(id)+'">Record adjustment</button>');
  else if(act==='detail')api('/admin/payouts/'+id).then((r)=>{const p=r.payout;modal('<h2>Payout '+esc(p.id)+'</h2><div class="card flat mt"><div class="col">'+
   [['Pandit ID',p.p],['Service date',fmtD(p.date)],['Gross',inr(p.gross)],['Commission',inr(p.comm||0)],['Tax / withholding',inr(p.tax||0)],['Refund',inr(p.refd||0)],['Adjustment',inr(p.adj||0)],['<b>Net payout</b>','<b>'+inr(p.amt)+'</b>'],['Status',badge(p.st)],['Hold reason',p.hr||'-'],['Hold note',p.hn||'-'],['Processing date',p.pd?fmtD(p.pd):'-'],['Disbursement date',p.dd?fmtD(p.dd):'-']].map((x)=>'<div class="row sp"><span class="mut">'+x[0]+'</span><span>'+(x[1]===undefined?'-':x[1])+'</span></div>').join('')+'</div></div><p class="sm mut mt">Transitions are recorded in the audit log with old and new status.</p><button class="btn blk mt" data-act="close">Close</button>')});
 },
