 async acampedit(d){const x=(db.campaigns||[]).find(c=>c.id===d.id);if(!x)return;modal('<h2>Edit campaign</h2><p class="sm mut">'+esc(x.id)+' — only DRAFT campaigns can be edited.</p><div class="frm mt"><label class="f">Name<input id="cen" value="'+esc(x.n)+'"></label><label class="f">Channel<select id="cech">'+['WhatsApp','Email','SMS','Push','In-App'].map(c=>'<option'+(x.ch===c?' selected':'')+'>'+c+'</option>').join('')+'</select></label><label class="f">Audience<select id="ceau">'+['All customers','Repeat customers','Plus members','Flagged customers'].map(a=>'<option'+(x.aud===a?' selected':'')+'>'+a+'</option>').join('')+'</select></label><label class="f">Message<textarea id="cem" maxlength="300">'+esc(x.msg||'')+'</textarea></label></div><button class="btn mt" data-act="acampeditok" data-id="'+esc(x.id)+'">Save changes</button>')},
 async acampeditok(d){await closeAnd(run(()=>api('/admin/campaigns/'+d.id,{method:'PATCH',body:{name:val('cen'),channel:val('cech'),audience:val('ceau'),message:val('cem')}}),'Campaign updated'))},
 acampsched(d){modal('<h2>Schedule campaign</h2><p class="sm mut">The message goes out automatically at the chosen time (due-sweep runs every minute). Sending requires a message.</p><div class="frm mt"><label class="f">Message (required)<textarea id="csm" maxlength="300"></textarea></label><label class="f">Send at<input id="csat" type="datetime-local"></label></div><button class="btn mt" data-act="acampschedok" data-id="'+esc(d.id)+'">Schedule</button>')},
 async acampschedok(d){const v=val('csat');if(!val('csm').trim())return toast('Message is required before scheduling');const when=v?new Date(v).getTime():Date.now();if(!when||isNaN(when))return toast('Pick a valid date and time');await closeAnd(run(()=>api('/admin/campaigns/'+d.id+'/schedule',{body:{message:val('csm'),scheduledAt:when}}),'Campaign scheduled'))},
 async acampsend(d){modal('<h2>Send this campaign now?</h2><p class="sm mut mt">It goes to its whole audience immediately. A note on why it is being sent early is kept on the audit trail.</p><div class="frm mt"><label class="f">Note (required, audited)<textarea id="acampsendr" style="min-height:70px" placeholder="Time-sensitive offer, corrected content, …"></textarea></label></div><div class="row mt"><button class="btn" data-act="acampsendok" data-id="'+esc(d.id)+'">Send now</button><button class="btn ghost" data-act="close">Not yet</button></div>')},
 async acampsendok(d){const r=(val('acampsendr')||'').trim();if(!r)return toast('A note is required for the audit trail');const x=await closeAnd(run(()=>api('/admin/campaigns/'+d.id+'/send',{body:{reason:r}})));if(x&&x.campaign&&x.campaign.delivered!==undefined)toast('Sent: '+x.campaign.delivered+' delivered, '+x.campaign.skipped+' skipped')},
 acampcancel(d){modal('<h2>Cancel this campaign?</h2><p class="sm mut mt">A cancelled campaign never sends. The reason is kept on the audit trail.</p><div class="frm mt"><label class="f">Reason (required, audited)<textarea id="acampcancelr" style="min-height:70px"></textarea></label></div><div class="row mt"><button class="btn bad" data-act="acampcancelok" data-id="'+esc(d.id)+'">Cancel campaign</button><button class="btn ghost" data-act="close">Keep campaign</button></div>')},
 async acampcancelok(d){const r=(val('acampcancelr')||'').trim();if(!r)return toast('A reason is required for the audit trail');await closeAnd(run(()=>api('/admin/campaigns/'+d.id+'/cancel',{body:{reason:r}}),'Campaign cancelled'))},
 async acampdetail(d){const r=await api('/admin/campaigns/'+d.id).catch(e=>{toast(e.message);return null});if(!r)return;const x=r.campaign,ds=r.deliveries||{};const stat=x.status==='SENT'?'Completed':x.status==='SCHEDULED'?'Confirmed':x.status==='FAILED'?'FAILED':x.status==='CANCELLED'?'Cancelled':'New';modal('<h2>'+esc(x.name)+'</h2><p class="sm mut">'+esc(x.id)+' '+badge(stat)+' · '+esc(x.channel)+' → '+esc(x.audience)+'</p><div class="grid g3 mt"><div class="card flat"><b>'+(ds.SENT||0)+'</b><br><span class="sm mut">Delivered</span></div><div class="card flat"><b>'+(ds.SKIPPED||0)+'</b><br><span class="sm mut">Skipped (no consent or no target)</span></div><div class="card flat"><b>'+(ds.FAILED||0)+'</b><br><span class="sm mut">Failed</span></div></div>'+(x.msg?'<p class="sm mt"><b>Message:</b> '+esc(x.msg)+'</p>':'')+(r.rows&&r.rows.length?'<h3 class="mt">Delivery records</h3><div class="tw"><table><thead><tr><th>Customer</th><th>Status</th><th>Detail</th><th>When</th></tr></thead><tbody>'+r.rows.slice(0,60).map(w=>'<tr><td>'+esc(w.userId)+'</td><td>'+w.status+'</td><td class="sm mut">'+esc(w.detail||'')+'</td><td class="sm mut">'+new Date(w.ts).toLocaleString('en-IN')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="sm mut mt">No delivery records yet — this campaign has not been sent.</p>'),1)},
 async apush(){const r=await run(()=>api('/admin/push',{body:{message:val('pnm')}}));if(r&&r.sent!==undefined)toast('Sent to '+r.sent+' customers')},
 /* Phases 27-29: Excel import — stateless preview, then confirmed commit. */
 async aimpprev(){const inp=document.getElementById('impf');const f=inp&&inp.files&&inp.files[0];if(!f)return toast('Choose an .xlsx file first');const fd=new FormData();fd.append('file',f);try{const r=await api('/admin/import/'+val('impk')+'/preview',{form:fd});PAGE.impPrev=r;PAGE.impPrev.kind=val('impk');render(true);toast(r.willCreate+' to create, '+r.willUpdate+' to update, '+r.duplicatesInFile+' duplicate(s) in file')}catch(e){toast(e.message)}},
 async aimpcommit(){const p=PAGE.impPrev;if(!p)return;const inp=document.getElementById('impf');const f=inp&&inp.files&&inp.files[0];if(!f){toast('Choose the same .xlsx file again to commit');return}modal('<h2>Commit this import?</h2><p class="sm mut mt">Creates '+p.willCreate+' new and updates '+p.willUpdate+' existing record(s), exactly as the preview showed.</p><div class="frm mt"><label class="f">Note (required, audited)<textarea id="aimpcommitr" style="min-height:70px" placeholder="Source of the file, batch reference …"></textarea></label></div><div class="row mt"><button class="btn" data-act="aimpcommitok">Import records</button><button class="btn ghost" data-act="close">Review again</button></div>')},
 async aimpcommitok(){const r=(val('aimpcommitr')||'').trim();if(!r)return toast('A note is required for the audit trail');const p=PAGE.impPrev;if(!p)return;const inp=document.getElementById('impf');const f=inp&&inp.files&&inp.files[0];if(!f){toast('Choose the same .xlsx file again to commit');return}const fd=new FormData();fd.append('file',f);fd.append('reason',r);try{const x=await api('/admin/import/'+p.kind+'/commit',{form:fd});PAGE.impPrev=null;await sync();render(true);toast('Imported: '+x.committed+' record(s) written')}catch(e){toast(e.message)}},
