const pmCard=m=>'<div class="card flat" style="width:170px;padding:8px"><picture>'+(m.thumbWebp?'<source type="image/webp" srcset="'+mediaUrl(m.thumbWebp)+'">':'')+'<img src="'+mediaUrl(m.thumb||m.url)+'" alt="'+esc(m.altText||m.origName||'photo')+'" loading="lazy" style="width:100%;height:110px;object-fit:cover;border-radius:8px;background:#eee"></picture><div class="sm mt">'+(m.status==='PENDING_ADMIN_REVIEW'?'<span class="badge">🟡 Pending review</span>':m.status==='APPROVED'?(m.isPublished?'<span class="badge ok">🟢 Live on site</span>':'<span class="badge info">🟢 Approved</span>'):'<span class="badge bad">🔴 Rejected</span>')+'</div><div class="sm mut">'+esc(m.altText||m.origName||'').slice(0,44)+'</div>'+(m.uploadDate?'<div class="sm mut">Puja date: '+esc(m.uploadDate)+'</div>':'')+(m.status==='REJECTED'&&m.rejectReason?'<div class="sm" style="color:var(--bad)">Admin: '+esc(m.rejectReason)+'</div>':'')+'<div class="sm mut">'+(m.createdAt?new Date(m.createdAt).toLocaleDateString('en-IN'):'')+'</div>'+(m.status==='PENDING_ADMIN_REVIEW'?'<button class="btn s bad mt" data-act="pmdel" data-id="'+m.id+'">Delete</button>':'')+'</div>';
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const f=ACT[el.dataset.act];if(f)f(el.dataset,el,e);if(el.dataset.act==='close')closeModal()});
document.addEventListener('click',e=>{if(e.target.id==='modal')closeModal();if(e.target.closest('.links a'))$('#links').classList.remove('open')});
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset||!el.dataset.in||el.dataset.re)return;if(el.tagName==='SELECT'||el.type==='date')return;const f=INP[el.dataset.in];if(f)f(el)});
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset||!el.dataset.in)return;const f=INP[el.dataset.in];if(f)f(el)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'||e.key===' '){const el=e.target.closest&&e.target.closest('.opt[data-act]');if(el){e.preventDefault();el.click()}}if(e.key==='Enter'){if(e.target.id==='aq')ACT.ask();if(e.target.id==='hq')ACT.hsearch()}});
window.addEventListener('hashchange',()=>{const p=pageOf();if(['account','portal','admin','book'].includes(p))sync().then(()=>render()).catch(()=>render());else render()});
const th=store.get('dp_theme',null);if(th)document.documentElement.dataset.theme=th;
(async()=>{try{await sync();if(token&&!session)setToken(null)}catch(e){$('#view').innerHTML='<div class="page"><div class="wrap"><h1>DaivikPuja is unavailable</h1><p class="mut mt">'+esc(e.message)+'</p></div></div>';return}footer();render()})();
